struct SubpaletteSampleProbe final {
    std::uint32_t count{};
    double x{};
    double y{};
};

void RecordSubpaletteSample(void* context, double x, double y) noexcept {
    auto* probe = static_cast<SubpaletteSampleProbe*>(context);
    if (probe != nullptr) {
        ++probe->count;
        probe->x = x;
        probe->y = y;
    }
}

