bool QueryCoreResourceUsage(
    ApplicationHost& state,
    inkpod::app::DocumentSessionId session,
    inkpod::app::Generation generation,
    InkpodResourceUsage& usage) noexcept {
    usage = {};
    usage.struct_size = sizeof(usage);
    return state.engine != nullptr
        && state.engine->Invoke(
               session,
               generation,
               [&usage](InkpodCore* core) {
                   return inkpod_core_get_resource_usage(core, &usage);
               },
               false,
               false) == INKPOD_STATUS_OK;
}

bool ValidateFixedResourceScenario(
    ApplicationHost& state,
    const char* scenario,
    std::uint64_t expected_workspaces,
    std::uint64_t expected_documents,
    std::uint64_t expected_views,
    std::uint64_t expected_groups) noexcept {
    const inkpod::app::ApplicationResourceUsage usage = state.ResourceUsage();
    if (scenario == nullptr
        || usage.workspace_window_count != expected_workspaces
        || usage.document_session_count != expected_documents
        || usage.document_view_count != expected_views
        || usage.editor_group_count != expected_groups
        || usage.editor_canvas_count != expected_groups
        || usage.registered_snapshot_sink_count != expected_groups
        || usage.auxiliary_canvas_count != expected_workspaces
        || usage.pane_instance_count != expected_workspaces * 10U
        || usage.thumbnails.budget_bytes == 0U
        || usage.thumbnails.resident_bytes > usage.thumbnails.budget_bytes
        || usage.renderer.gpu_tile_budget_bytes == 0U
        || usage.renderer.gpu_tile_bytes > usage.renderer.gpu_tile_budget_bytes
         || usage.renderer.surface_count
             != usage.editor_canvas_count + usage.auxiliary_canvas_count) {
        std::fprintf(
            stderr,
            "G13 resource mismatch scenario=%s workspaces=%llu/%llu "
            "documents=%llu/%llu views=%llu/%llu groups=%llu/%llu "
            "editor_canvases=%llu snapshot_sinks=%llu auxiliary_canvases=%llu panes=%llu "
            "thumbnail=%llu/%llu renderer_surfaces=%llu renderer_budget=%llu/%llu\n",
            scenario == nullptr ? "(null)" : scenario,
            static_cast<unsigned long long>(usage.workspace_window_count),
            static_cast<unsigned long long>(expected_workspaces),
            static_cast<unsigned long long>(usage.document_session_count),
            static_cast<unsigned long long>(expected_documents),
            static_cast<unsigned long long>(usage.document_view_count),
            static_cast<unsigned long long>(expected_views),
            static_cast<unsigned long long>(usage.editor_group_count),
            static_cast<unsigned long long>(expected_groups),
            static_cast<unsigned long long>(usage.editor_canvas_count),
            static_cast<unsigned long long>(
                usage.registered_snapshot_sink_count),
            static_cast<unsigned long long>(usage.auxiliary_canvas_count),
            static_cast<unsigned long long>(usage.pane_instance_count),
            static_cast<unsigned long long>(usage.thumbnails.resident_bytes),
            static_cast<unsigned long long>(usage.thumbnails.budget_bytes),
            static_cast<unsigned long long>(usage.renderer.surface_count),
            static_cast<unsigned long long>(usage.renderer.gpu_tile_bytes),
            static_cast<unsigned long long>(usage.renderer.gpu_tile_budget_bytes));
        return false;
    }

    std::uint64_t document_tile_bytes{};
    std::uint64_t history_bytes{};
    std::uint64_t reference_bytes{};
    for (std::size_t index = 0U; index < state.Documents().Count(); ++index) {
        const auto* document = state.Documents().SessionAt(index);
        InkpodResourceUsage core{};
        if (document == nullptr
            || !QueryCoreResourceUsage(
                state, document->id, document->generation, core)) {
            return false;
        }
        document_tile_bytes += core.document_tile_bytes;
        history_bytes += core.history_bytes;
        reference_bytes += core.reference_light_table_bytes;
    }

    for (std::size_t workspace_index = 0U;
         workspace_index < state.Workspaces().Count();
         ++workspace_index) {
        const auto* workspace = state.Workspaces().At(workspace_index);
        if (workspace == nullptr) {
            return false;
        }
        inkpod::app::PaneResourceUsage layer_usage{};
        inkpod::app::PaneResourceUsage sequence_usage{};
        if (!state.GetPaneResourceUsage(workspace->pane_ids.layer, layer_usage)
            || !state.GetPaneResourceUsage(
                workspace->pane_ids.sequence, sequence_usage)
            || layer_usage.workspace != workspace->id
            || sequence_usage.workspace != workspace->id) {
            return false;
        }
        for (std::size_t group_index = 0U;
             group_index < workspace->editors.GroupCount();
             ++group_index) {
            const auto* group = workspace->editors.GroupAt(group_index);
            inkpod::renderer::RendererSurfaceResourceUsage surface{};
            const auto* document = group == nullptr
                ? nullptr
                : state.Documents().FindByView(group->ActiveView());
            if (group == nullptr || document == nullptr
                || !state.renderer->GetSurfaceResourceUsage(
                    group->canvas_id, group->generation, surface)
                || surface.route.canvas != group->canvas_id
                || surface.route.document_session != document->id
                || surface.route.document_view != group->ActiveView()
                || surface.route.document_generation != document->generation
                || surface.route.surface_generation != group->generation) {
                return false;
            }
        }
    }

    std::fprintf(
        stdout,
        "inkpod-g13-resource scenario=%s workspaces=%llu documents=%llu "
        "views=%llu editor_canvases=%llu snapshot_sinks=%llu "
        "auxiliary_canvases=%llu panes=%llu "
        "core_tile_bytes=%llu history_bytes=%llu reference_bytes=%llu "
        "thumbnail_bytes=%llu renderer_bytes=%llu\n",
        scenario,
        static_cast<unsigned long long>(usage.workspace_window_count),
        static_cast<unsigned long long>(usage.document_session_count),
        static_cast<unsigned long long>(usage.document_view_count),
        static_cast<unsigned long long>(usage.editor_canvas_count),
        static_cast<unsigned long long>(usage.registered_snapshot_sink_count),
        static_cast<unsigned long long>(usage.auxiliary_canvas_count),
        static_cast<unsigned long long>(usage.pane_instance_count),
        static_cast<unsigned long long>(document_tile_bytes),
        static_cast<unsigned long long>(history_bytes),
        static_cast<unsigned long long>(reference_bytes),
        static_cast<unsigned long long>(usage.thumbnails.resident_bytes),
        static_cast<unsigned long long>(
            usage.renderer.retained_snapshot_bytes
            + usage.renderer.pending_snapshot_bytes
            + usage.renderer.gpu_tile_bytes
            + usage.renderer.swap_chain_bytes));
    return true;
}

int RunLocatorPaneSmoke(ApplicationHost& state) noexcept {
    const HWND pane = state.Workspace().locator_palette;
    const HWND workspace_window = state.Workspace().windows.window;
    const HMENU menu = GetMenu(workspace_window);
    if (pane == nullptr || workspace_window == nullptr || menu == nullptr
        || state.Workspace().windows.workspace.dock.IsPaneVisible(
            DockPaneType::Locator)
        || GetParent(pane) != workspace_window
        || (static_cast<DWORD>(GetWindowLongPtrW(pane, GWL_STYLE)) & WS_CHILD) == 0U
        || (static_cast<DWORD>(GetWindowLongPtrW(pane, GWL_EXSTYLE))
            & (WS_EX_TOPMOST | WS_EX_NOACTIVATE | WS_EX_TOOLWINDOW)) != 0U
        || !WindowHasAccessibleName(pane)) {
        return 850;
    }
    const UINT dpi = GetDpiForWindow(workspace_window);
    const HMONITOR monitor = MonitorFromWindow(
        workspace_window, MONITOR_DEFAULTTONEAREST);
    MONITORINFO monitor_info{sizeof(monitor_info)};
    if (monitor == nullptr || GetMonitorInfoW(monitor, &monitor_info) == FALSE) {
        return 1001;
    }
    const int work_width = std::max(
        1,
        static_cast<int>(
            monitor_info.rcWork.right - monitor_info.rcWork.left));
    const int work_height = std::max(
        1,
        static_cast<int>(
            monitor_info.rcWork.bottom - monitor_info.rcWork.top));
    if (SetWindowPos(
            workspace_window,
            nullptr,
            monitor_info.rcWork.left,
            monitor_info.rcWork.top,
            std::min(
                work_width, MulDiv(1'400, static_cast<int>(dpi), 96)),
            std::min(
                work_height, MulDiv(900, static_cast<int>(dpi), 96)),
            SWP_NOACTIVATE | SWP_NOZORDER) == FALSE) {
        return 1001;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_WINDOW_LOCATOR,
            0) != 1
        || !state.Workspace().windows.workspace.dock.IsPaneVisible(
            DockPaneType::Locator)
        || (GetMenuState(menu, IDM_WINDOW_LOCATOR, MF_BYCOMMAND) & MF_CHECKED) == 0U
        || GetDlgItem(pane, IDC_LOCATOR_TARGET) == nullptr
        || GetDlgItem(pane, IDC_LOCATOR_PIN) == nullptr
        || !WindowUsesNamedIconButton(GetDlgItem(pane, IDC_LOCATOR_PIN))
        || GetDlgItem(pane, IDC_LOCATOR_NEIGHBORHOOD) == nullptr
        || GetDlgItem(pane, IDC_LOCATOR_FIXED) == nullptr
        || GetDlgItem(pane, IDC_LOCATOR_AUTOSCROLL) == nullptr
        || !PaneButtonsFit(pane)
        || !PaneButtonsFit(state.Workspace().windows.color_pane)
        || !PaneButtonsFit(state.Workspace().panes.layer_palette)) {
        return 851;
    }
    if (const int resize_failure = VerifyPaneHeightResizeRepaint(
            pane, IDC_LOCATOR_FIXED, 11160);
        resize_failure != 0) {
        return resize_failure;
    }
    const HWND locator_header =
        state.Workspace().windows.dock_host.HeaderWindow(DockPaneType::Locator);
    std::array<wchar_t, 64U> locator_title{};
    TCITEMW locator_tab{};
    locator_tab.mask = TCIF_TEXT;
    locator_tab.pszText = locator_title.data();
    locator_tab.cchTextMax = static_cast<int>(locator_title.size());
    RECT locator_header_bounds{};
    RECT locator_content_bounds{};
    if (!WindowHasVisibleStyle(pane)) {
        return 1002;
    }
    if (locator_header == nullptr) {
        return 987;
    }
    if (!WindowHasVisibleStyle(locator_header)) {
        return 988;
    }
    if (TabCtrl_GetItemCount(locator_header) != 1) {
        return 989;
    }
    if (TabCtrl_GetItem(locator_header, 0, &locator_tab) == FALSE) {
        return 990;
    }
    if (std::wcscmp(
            locator_title.data(), std::wstring(UiText(UiStringId::Text0411)).c_str()) != 0) {
        return 991;
    }
    if (!AccessibleChildNameContains(
            locator_header, std::wstring(UiText(UiStringId::Text0411)))) {
        return 992;
    }
    if (GetWindowRect(locator_header, &locator_header_bounds) == FALSE
        || GetWindowRect(pane, &locator_content_bounds) == FALSE) {
        return 993;
    }
    if (locator_header_bounds.bottom > locator_content_bounds.top
        || locator_header_bounds.bottom <= locator_header_bounds.top) {
        return 994;
    }
    std::array<wchar_t, 256U> target_text{};
    if (GetDlgItemTextW(
            pane,
            IDC_LOCATOR_TARGET,
            target_text.data(),
            static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(
               target_text.data(), UiText(UiStringId::FollowingPrefix))
            != target_text.data()) {
        return 852;
    }
    std::array<wchar_t, 256U> coordinate_text{};
    std::array<wchar_t, 256U> selection_text{};
    std::array<wchar_t, 256U> color_text{};
    GetDlgItemTextW(
        pane,
        IDC_LOCATOR_COORDINATE,
        coordinate_text.data(),
        static_cast<int>(coordinate_text.size()));
    GetDlgItemTextW(
        pane,
        IDC_LOCATOR_SELECTION,
        selection_text.data(),
        static_cast<int>(selection_text.size()));
    GetDlgItemTextW(
        pane,
        IDC_LOCATOR_COLOR,
        color_text.data(),
        static_cast<int>(color_text.size()));
    const auto* initial_binding = state.routing.pane_targets.Find(
        state.routing.locator_pane);
    const auto& locator_state = state.Workspace().locator_dialog;
    inkpod::windows::ui::panes::LocatorPaneView repeated_view{};
    repeated_view.target_text = target_text.data();
    repeated_view.coordinate_text = coordinate_text.data();
    repeated_view.selection_text = selection_text.data();
    repeated_view.color_text = color_text.data();
    repeated_view.neighborhood_width = locator_state.neighborhood_width;
    repeated_view.neighborhood_height = locator_state.neighborhood_height;
    repeated_view.neighborhood_origin_x = locator_state.neighborhood_origin_x;
    repeated_view.neighborhood_origin_y = locator_state.neighborhood_origin_y;
    repeated_view.neighborhood = locator_state.neighborhood;
    repeated_view.valid = locator_state.neighborhood_width != 0U
        && locator_state.neighborhood_height != 0U;
    repeated_view.pinned = initial_binding != nullptr
        && initial_binding->policy == inkpod::app::PaneTargetPolicy::PinnedDocument;
    repeated_view.fixed_mode = state.Workspace().locator_fixed_mode;
    repeated_view.auto_scroll = state.Workspace().locator_auto_scroll;
    constexpr UINT_PTR kTargetMessageCounterSubclass = 1U;
    WindowMessageCounter target_message_counter{WM_SETTEXT};
    const HWND target_control = GetDlgItem(pane, IDC_LOCATOR_TARGET);
    if (target_control == nullptr
        || SetWindowSubclass(
               target_control,
               WindowMessageCounterProcedure,
               kTargetMessageCounterSubclass,
               reinterpret_cast<DWORD_PTR>(&target_message_counter)) == FALSE) {
        return 11004;
    }
    inkpod::windows::ui::panes::UpdateLocatorPaneDialog(
        pane, repeated_view);
    RemoveWindowSubclass(
        target_control,
        WindowMessageCounterProcedure,
        kTargetMessageCounterSubclass);
    if (target_message_counter.count != 0U) {
        return 11004;
    }
    inkpod::windows::ui::panes::LocatorPaneView expanded_selection_view =
        repeated_view;
    std::array<wchar_t, 33U> expanded_selection_text{};
    expanded_selection_text.fill(L'W');
    expanded_selection_text.back() = L'\0';
    expanded_selection_view.selection_text = expanded_selection_text.data();
    inkpod::windows::ui::panes::UpdateLocatorPaneDialog(
        pane, expanded_selection_view);
    inkpod::windows::ui::panes::UpdateLocatorPaneDialog(
        pane, repeated_view);
    std::array<wchar_t, 256U> restored_selection_text{};
    GetDlgItemTextW(
        pane,
        IDC_LOCATOR_SELECTION,
        restored_selection_text.data(),
        static_cast<int>(restored_selection_text.size()));
    if (std::wcscmp(restored_selection_text.data(), selection_text.data()) != 0) {
        return 11005;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_LOCATOR_PIN,
            0) != 1) {
        return 853;
    }
    const auto* binding = state.routing.pane_targets.Find(
        state.routing.locator_pane);
    target_text.fill(L'\0');
    if (binding == nullptr
        || binding->policy != inkpod::app::PaneTargetPolicy::PinnedDocument
        || GetDlgItemTextW(
               pane,
               IDC_LOCATOR_TARGET,
               target_text.data(),
               static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(
               target_text.data(), UiText(UiStringId::PinnedPrefix))
            != target_text.data()
        || HasJapaneseCharacters(target_text.data())
        || !PaneButtonsFit(pane)) {
        return 854;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_LOCATOR_FIXED,
            0) != 1
        || !state.Workspace().locator_fixed_mode
        || SendMessageW(
               state.Workspace().windows.window,
               WM_COMMAND,
               IDM_LOCATOR_AUTOSCROLL,
               0) != 1
        || state.Workspace().locator_auto_scroll) {
        return 855;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_LOCATOR_FIXED,
            0) != 1
        || SendMessageW(
               state.Workspace().windows.window,
               WM_COMMAND,
               IDM_LOCATOR_AUTOSCROLL,
               0) != 1
        || SendMessageW(
               state.Workspace().windows.window,
               WM_COMMAND,
               IDM_LOCATOR_PIN,
               0) != 1
        || state.Workspace().locator_fixed_mode
        || !state.Workspace().locator_auto_scroll
        || state.routing.pane_targets.Find(state.routing.locator_pane)->policy
            != inkpod::app::PaneTargetPolicy::FollowActiveView
        || GetDlgItemTextW(
               pane,
               IDC_LOCATOR_TARGET,
               target_text.data(),
               static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(
               target_text.data(), UiText(UiStringId::FollowingPrefix))
            != target_text.data()
        || HasJapaneseCharacters(target_text.data())) {
        return 856;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_WINDOW_LOCATOR,
            0) != 1
        || state.Workspace().windows.workspace.dock.IsPaneVisible(
            DockPaneType::Locator)
        || (GetMenuState(menu, IDM_WINDOW_LOCATOR, MF_BYCOMMAND) & MF_CHECKED) != 0U) {
        return 857;
    }
    return 0;
}

bool VerifyHorizontalSequenceLayout(ApplicationHost& state) noexcept try {
    using inkpod::windows::ui::panes::SequencePaneCellView;
    using inkpod::windows::ui::panes::SequencePaneSelection;
    using inkpod::windows::ui::panes::SequencePaneView;
    using inkpod::windows::ui::panes::UpdateSequencePaneDialog;
    using inkpod::windows::ui::panes::UpdateSequencePaneSelection;
    const HWND pane = state.Workspace().sequence_palette;
    const HWND list = GetDlgItem(pane, IDC_SEQUENCE_CELLS);
    RECT original_bounds{};
    if (GetWindowRect(pane, &original_bounds) == FALSE) {
        return false;
    }
    constexpr UINT_PTR kSequenceResizeProbe = 11220U;
    constexpr UINT_PTR kSequenceSelectionGeometryProbe = 11221U;
    constexpr UINT_PTR kSequenceSelectionColumnProbe = 11222U;
    constexpr UINT_PTR kSequenceSelectionTargetProbe = 11223U;
    WindowMessageCounter sequence_list_rebuilds{LB_RESETCONTENT};
    WindowMessageCounter sequence_list_moves{WM_WINDOWPOSCHANGING};
    WindowMessageCounter sequence_column_updates{LB_SETCOLUMNWIDTH};
    WindowMessageCounter sequence_target_updates{WM_SETTEXT};
    inkpod::windows::ui::ThumbnailCache thumbnails;
    struct RestoreSequencePane final {
        HWND pane{};
        HWND list{};
        HWND focus{};
        RECT bounds{};
        SequencePaneView view;
        inkpod::windows::ui::panes::SequencePaneDialogState* state{};
        inkpod::windows::ui::ThumbnailCache* thumbnails{};
        ~RestoreSequencePane() noexcept {
            RemoveWindowSubclass(list, WindowMessageCounterProcedure, kSequenceResizeProbe);
            RemoveWindowSubclass(list, WindowMessageCounterProcedure,
                kSequenceSelectionGeometryProbe);
            RemoveWindowSubclass(list, WindowMessageCounterProcedure,
                kSequenceSelectionColumnProbe);
            RemoveWindowSubclass(GetDlgItem(pane, IDC_SEQUENCE_TARGET),
                WindowMessageCounterProcedure, kSequenceSelectionTargetProbe);
            state->thumbnail_cache = thumbnails;
            UpdateSequencePaneDialog(pane, std::move(view));
            SetWindowPos(pane, nullptr, 0, 0,
                bounds.right - bounds.left, bounds.bottom - bounds.top,
                SWP_NOMOVE | SWP_NOACTIVATE | SWP_NOZORDER);
            if (focus != nullptr && IsWindow(focus) != FALSE) {
                SetFocus(focus);
            }
        }
    } restore{pane, list, GetFocus(), original_bounds,
        state.Workspace().sequence_dialog.view,
        &state.Workspace().sequence_dialog,
        state.Workspace().sequence_dialog.thumbnail_cache};
    state.Workspace().sequence_dialog.thumbnail_cache = &thumbnails;
    SequencePaneView sample = restore.view;
    sample.target_available = true;
    sample.cut_editable = false;
    sample.active_index = 5U;
    sample.catalog = {state.Document().id, state.Document().generation, 1U, 1U, 32U};
    sample.cells.clear();
    for (std::uint32_t index = 0U; index < 32U; ++index) {
        SequencePaneCellView cell{};
        cell.sequence_index = index;
        cell.cell_number = index * 2U + 1U;
        cell.width = 320U;
        cell.height = 240U;
        cell.name = L"Frame " + std::to_wstring(cell.cell_number);
        cell.document_uuid_high = 1U;
        cell.document_uuid_low = index + 1U;
        cell.thumbnail_width = 1U;
        cell.thumbnail_height = 1U;
        cell.thumbnail_stride_bytes = 4U;
        cell.thumbnail_key = {
            state.Workspace().pane_ids.sequence,
            state.Document().id, state.Document().generation,
            static_cast<std::uint64_t>(index) + 1U, 1U,
            inkpod::windows::ui::ThumbnailKind::Sequence};
        if (!thumbnails.Put(cell.thumbnail_key, 1U, 1U, 4U,
                inkpod::windows::ui::ThumbnailPixelLayout::Rgba8,
                std::vector<std::uint8_t>{static_cast<std::uint8_t>(index), 40U, 80U, 255U})) {
            return false;
        }
        sample.cells.push_back(std::move(cell));
    }
    sample.thumbnail_generation = thumbnails.InvalidationGeneration(
        inkpod::windows::ui::ThumbnailKind::Sequence);
    UpdateSequencePaneDialog(pane, sample);
    std::wstring first_label;
    if (!ReadListItemText(list, 0, first_label)
        || first_label.find(L"Frame 1") == std::wstring::npos
        || !AccessibleChildNameContains(list, L"Frame 1")) {
        std::fprintf(stderr, "sequence frame native/accessibility label missing\n");
        return false;
    }
    if (SetWindowSubclass(list, WindowMessageCounterProcedure,
            kSequenceResizeProbe,
            reinterpret_cast<DWORD_PTR>(&sequence_list_rebuilds)) == FALSE) {
        return false;
    }
    const int dpi = static_cast<int>(GetDpiForWindow(pane));
    const auto scale = [dpi](int dip) { return MulDiv(dip, dpi, 96); };
    const auto one_row = [list]() {
        RECT first{};
        RECT second{};
        RECT last{};
        RECT client{};
        return GetClientRect(list, &client) != FALSE
            && SendMessageW(list, LB_GETITEMRECT, 0,
                reinterpret_cast<LPARAM>(&first)) != LB_ERR
            && SendMessageW(list, LB_GETITEMRECT, 1,
                reinterpret_cast<LPARAM>(&second)) != LB_ERR
            && SendMessageW(list, LB_GETITEMRECT, 31,
                reinterpret_cast<LPARAM>(&last)) != LB_ERR
            && first.top == second.top && first.top == last.top
            && first.bottom == second.bottom && first.bottom == last.bottom
            && first.left < second.left && second.left < last.left
            && first.bottom - first.top == client.bottom - client.top
            && client.bottom - client.top > 0 && client.bottom - client.top <= 255;
    };
    const auto clean_paint = [pane]() {
        RECT update{};
        if (GetUpdateRect(pane, &update, FALSE) != FALSE) {
            return false;
        }
        for (HWND child = GetWindow(pane, GW_CHILD); child != nullptr;
             child = GetWindow(child, GW_HWNDNEXT)) {
            if ((GetWindowLongPtrW(child, GWL_STYLE) & WS_VISIBLE) != 0
                && GetUpdateRect(child, &update, FALSE) != FALSE) {
                return false;
            }
        }
        return true;
    };
    SetFocus(list);
    const HWND focused = GetFocus();
    SendMessageW(list, LB_SETTOPINDEX, 8U, 0);
    for (const auto& dimensions : std::array<POINT, 4U>{
             POINT{560, 140}, POINT{760, 176}, POINT{560, 500}, POINT{560, 140}}) {
        if (SetWindowPos(pane, nullptr, 0, 0,
                scale(dimensions.x), scale(dimensions.y),
                SWP_NOMOVE | SWP_NOACTIVATE | SWP_NOZORDER) == FALSE
            || !one_row() || !clean_paint()
            || SendMessageW(list, LB_GETTOPINDEX, 0, 0) != 8
            || SendMessageW(list, LB_GETCURSEL, 0, 0) != 5
            || GetFocus() != focused || sequence_list_rebuilds.count != 0U) {
            std::fprintf(stderr,
                "sequence horizontal resize failed: size=%ld,%ld one_row=%d clean=%d "
                "first=%lld selected=%lld focus=%d rebuilds=%u\n",
                dimensions.x, dimensions.y, one_row() ? 1 : 0, clean_paint() ? 1 : 0,
                static_cast<long long>(SendMessageW(list, LB_GETTOPINDEX, 0, 0)),
                static_cast<long long>(SendMessageW(list, LB_GETCURSEL, 0, 0)),
                GetFocus() == focused ? 1 : 0, sequence_list_rebuilds.count);
            return false;
        }
    }
    const auto* retained_width_cells =
        state.Workspace().sequence_dialog.view.cells.data();
    const auto* retained_width_labels =
        state.Workspace().sequence_dialog.item_labels.data();
    const std::uint64_t retained_thumbnail_generation =
        state.Workspace().sequence_dialog.view.thumbnail_generation;
    int previous_extent{};
    for (const std::uint32_t width : {
             app::kMinimumSequenceThumbnailWidthDip,
             app::kDefaultSequenceThumbnailWidthDip,
             app::kMaximumSequenceThumbnailWidthDip}) {
        RECT item{};
        if (!inkpod::windows::ui::panes::SetSequencePaneThumbnailWidthDip(
                pane, width)) {
            return false;
        }
        const int extent =
            inkpod::windows::ui::panes::MeasureSequencePaneBottomExtentDip(
                pane, scale(560));
        if (SendMessageW(list, LB_GETITEMRECT, 0U,
                   reinterpret_cast<LPARAM>(&item)) == LB_ERR
            || item.right - item.left != scale(static_cast<int>(width) + 48)
            || SendMessageW(list, LB_GETTOPINDEX, 0, 0) != 8
            || SendMessageW(list, LB_GETCURSEL, 0, 0) != 5
            || GetFocus() != focused || sequence_list_rebuilds.count != 0U
            || state.Workspace().sequence_dialog.view.cells.data()
                != retained_width_cells
            || state.Workspace().sequence_dialog.item_labels.data()
                != retained_width_labels
            || state.Workspace().sequence_dialog.view.thumbnail_generation
                != retained_thumbnail_generation
            || (previous_extent != 0 && extent < previous_extent)) {
            std::fputs("sequence thumbnail-width presentation changed retained state\n",
                stderr);
            return false;
        }
        previous_extent = extent;
    }
    const SIZE landscape =
        inkpod::windows::ui::panes::ComputeSequenceThumbnailSize(320U, 180U, 96);
    const SIZE portrait =
        inkpod::windows::ui::panes::ComputeSequenceThumbnailSize(180U, 320U, 96);
    const SIZE square =
        inkpod::windows::ui::panes::ComputeSequenceThumbnailSize(64U, 64U, 96);
    if (landscape.cx != 96 || landscape.cy != 54
        || portrait.cx != 54 || portrait.cy != 96
        || square.cx != 96 || square.cy != 96
        || !inkpod::windows::ui::panes::SetSequencePaneThumbnailWidthDip(
            pane, app::kDefaultSequenceThumbnailWidthDip)) {
        std::fputs("sequence thumbnail aspect-ratio contract failed\n", stderr);
        return false;
    }
    UpdateSequencePaneDialog(pane, sample);
    if (sequence_list_rebuilds.count != 0U
        || SendMessageW(list, LB_GETTOPINDEX, 0, 0) != 8) {
        std::fprintf(stderr, "sequence unchanged presentation rebuilt/scrolled the list\n");
        return false;
    }
    if (SetWindowSubclass(list, WindowMessageCounterProcedure,
            kSequenceSelectionGeometryProbe,
            reinterpret_cast<DWORD_PTR>(&sequence_list_moves)) == FALSE
        || SetWindowSubclass(list, WindowMessageCounterProcedure,
            kSequenceSelectionColumnProbe,
            reinterpret_cast<DWORD_PTR>(&sequence_column_updates)) == FALSE
        || SetWindowSubclass(GetDlgItem(pane, IDC_SEQUENCE_TARGET),
            WindowMessageCounterProcedure, kSequenceSelectionTargetProbe,
            reinterpret_cast<DWORD_PTR>(&sequence_target_updates)) == FALSE) {
        return false;
    }
    const auto* retained_cells = state.Workspace().sequence_dialog.view.cells.data();
    const auto* retained_labels = state.Workspace().sequence_dialog.item_labels.data();
    const auto select = [&](std::uint32_t index) {
        return UpdateSequencePaneSelection(pane, SequencePaneSelection{
            sample.catalog, index, sample.target_text,
            sample.pinned, sample.auto_sequence_truncated, sample.wrap_navigation});
    };
    for (std::uint32_t repeat = 0U; repeat < 8U; ++repeat) {
        if (!select(5U) || SendMessageW(list, LB_GETTOPINDEX, 0, 0) != 8
            || SendMessageW(list, LB_GETCURSEL, 0, 0) != 5
            || GetFocus() != focused
            || state.Workspace().sequence_dialog.view.cells.data() != retained_cells
            || state.Workspace().sequence_dialog.item_labels.data() != retained_labels) {
            std::fputs("sequence selection-only update replaced metadata or viewport\n", stderr);
            return false;
        }
    }
    if (!select(9U) || SendMessageW(list, LB_GETTOPINDEX, 0, 0) != 8
        || SendMessageW(list, LB_GETCURSEL, 0, 0) != 9 || !select(31U)) {
        return false;
    }
    RECT selected_bounds{};
    RECT sequence_client{};
    if (SendMessageW(list, LB_GETITEMRECT, 31U,
            reinterpret_cast<LPARAM>(&selected_bounds)) == LB_ERR
        || GetClientRect(list, &sequence_client) == FALSE
        || selected_bounds.left < sequence_client.left
        || selected_bounds.right > sequence_client.right
        || sequence_list_rebuilds.count != 0U || sequence_list_moves.count != 0U
        || sequence_column_updates.count != 0U || sequence_target_updates.count != 0U
        || GetFocus() != focused || !select(5U)) {
        std::fputs("sequence selection-only update changed geometry or failed to reveal frame\n",
            stderr);
        return false;
    }
    std::array stale_catalogs{
        sample.catalog, sample.catalog, sample.catalog, sample.catalog, sample.catalog};
    ++stale_catalogs[0].owner_generation;
    ++stale_catalogs[1].revision;
    ++stale_catalogs[2].cell_count;
    stale_catalogs[3].session = inkpod::app::DocumentSessionId{UINT64_MAX};
    stale_catalogs[4].generation = inkpod::app::Generation{UINT64_MAX};
    for (const auto& stale_catalog : stale_catalogs) {
        if (UpdateSequencePaneSelection(pane, SequencePaneSelection{
                stale_catalog, 12U, sample.target_text,
                sample.pinned, sample.auto_sequence_truncated, sample.wrap_navigation})
            || state.Workspace().sequence_dialog.view.active_index != 5U) {
            return false;
        }
    }
    const SequencePaneSelection changed_header{
        sample.catalog, 5U, sample.target_text + L" selection fixture",
        !sample.pinned, !sample.auto_sequence_truncated, !sample.wrap_navigation};
    if (!UpdateSequencePaneSelection(pane, changed_header)
        || state.Workspace().sequence_dialog.view.pinned != changed_header.pinned
        || state.Workspace().sequence_dialog.view.auto_sequence_truncated
            != changed_header.auto_sequence_truncated
        || state.Workspace().sequence_dialog.view.wrap_navigation
            != changed_header.wrap_navigation
        || sequence_target_updates.count != 1U
        || !UpdateSequencePaneSelection(pane, changed_header)
        || sequence_target_updates.count != 1U || !select(5U)
        || sequence_target_updates.count != 2U
        || sequence_list_rebuilds.count != 0U || sequence_list_moves.count != 0U
        || sequence_column_updates.count != 0U || GetFocus() != focused) {
        return false;
    }
    // Another pane's removal changes the global generation, but does not remove
    // this pane's keys or force metadata/thumbnail regeneration here.
    auto unrelated_key = sample.cells.front().thumbnail_key;
    unrelated_key.pane = inkpod::app::PaneInstanceId{UINT64_MAX};
    if (!thumbnails.Put(unrelated_key, 1U, 1U, 4U,
            inkpod::windows::ui::ThumbnailPixelLayout::Rgba8,
            std::vector<std::uint8_t>{1U, 2U, 3U, 255U})) {
        return false;
    }
    thumbnails.RemovePane(unrelated_key.pane);
    if (!select(5U)
        || state.Workspace().sequence_dialog.view.thumbnail_generation
            != thumbnails.InvalidationGeneration(
                inkpod::windows::ui::ThumbnailKind::Sequence)
        || state.Workspace().sequence_dialog.view.cells.data() != retained_cells
        || state.Workspace().sequence_dialog.item_labels.data() != retained_labels) {
        return false;
    }
    // A genuine shared-budget eviction must refuse reuse without changing the
    // committed selection. The caller will rebuild through the full path.
    if (!thumbnails.SetBudgetBytes(4U) || select(12U)
        || state.Workspace().sequence_dialog.view.active_index != 5U
        || state.Workspace().sequence_dialog.view.cells.data() != retained_cells
        || state.Workspace().sequence_dialog.item_labels.data() != retained_labels) {
        return false;
    }
    SendMessageW(list, LB_SETTOPINDEX, 8U, 0);
    SendMessageW(list, WM_MOUSEHWHEEL, MAKEWPARAM(0U, WHEEL_DELTA), 0);
    const LRESULT scrolled = SendMessageW(list, LB_GETTOPINDEX, 0, 0);
    if (scrolled <= 8 || SendMessageW(list, LB_GETCURSEL, 0, 0) != 5) {
        std::fprintf(stderr, "sequence horizontal wheel failed to preserve the active cell\n");
        return false;
    }
    // The minimum includes the DockHost's 28-DIP tab header. Cut-only actions
    // remain reachable without forcing the ordinary sequence to reserve a row.
    sample.cut_editable = true;
    UpdateSequencePaneDialog(pane, sample);
    const auto* descriptor = inkpod::windows::ui::FindPaneDescriptor(DockPaneType::Sequence);
    if (descriptor == nullptr || descriptor->minimum_height_dip >= 200
        || SetWindowPos(pane, nullptr, 0, 0,
            scale(descriptor->minimum_width_dip),
            scale(descriptor->minimum_height_dip - 28),
            SWP_NOMOVE | SWP_NOACTIVATE | SWP_NOZORDER) == FALSE
        || !one_row() || !clean_paint() || !PaneButtonsFit(pane)) {
        std::fprintf(stderr, "sequence Cut minimum layout failed: one_row=%d clean=%d buttons=%d\n",
            one_row() ? 1 : 0, clean_paint() ? 1 : 0, PaneButtonsFit(pane) ? 1 : 0);
        return false;
    }
    return VerifyPaneHeightResizeRepaint(pane, IDC_SEQUENCE_RENUMBER, 11230) == 0;
} catch (const std::bad_alloc&) {
    return false;
}

int RunSequencePaneSmoke(ApplicationHost& state) noexcept {
    const HWND pane = state.Workspace().sequence_palette;
    const HMENU menu = GetMenu(state.Workspace().windows.window);
    if (pane == nullptr || menu == nullptr
        || state.Workspace().windows.workspace.dock.IsPaneVisible(
            DockPaneType::Sequence)
        || GetParent(pane) != state.Workspace().windows.window
        || (static_cast<DWORD>(GetWindowLongPtrW(pane, GWL_STYLE)) & WS_CHILD) == 0U
        || (static_cast<DWORD>(GetWindowLongPtrW(pane, GWL_EXSTYLE))
            & (WS_EX_TOPMOST | WS_EX_NOACTIVATE | WS_EX_TOOLWINDOW)) != 0U
        || !WindowHasAccessibleName(pane)) {
        std::fprintf(
            stderr,
            "sequence pane initial state mismatch: pane=%p menu=%p visible=%d "
            "parent_matches=%d style=%llu exstyle=%llu accessible=%d\n",
            static_cast<void*>(pane),
            static_cast<void*>(menu),
            state.Workspace().windows.workspace.dock.IsPaneVisible(
                DockPaneType::Sequence)
                ? 1
                : 0,
            GetParent(pane) == state.Workspace().windows.window ? 1 : 0,
            static_cast<unsigned long long>(GetWindowLongPtrW(pane, GWL_STYLE)),
            static_cast<unsigned long long>(GetWindowLongPtrW(pane, GWL_EXSTYLE)),
            WindowHasAccessibleName(pane) ? 1 : 0);
        return 867;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_WINDOW_SEQUENCE,
            0) != 1
        || !state.Workspace().windows.workspace.dock.IsPaneVisible(
            DockPaneType::Sequence)
        || state.Workspace().windows.dock_host.SplitterWindow(
               DockZone::Bottom, DockSplitterKind::ZoneExtent) != nullptr
        || (GetMenuState(menu, IDM_WINDOW_SEQUENCE, MF_BYCOMMAND) & MF_CHECKED) == 0U
        || GetDlgItem(pane, IDC_SEQUENCE_TARGET) == nullptr
        || GetDlgItem(pane, IDC_SEQUENCE_PIN) == nullptr
        || !WindowUsesNamedIconButton(GetDlgItem(pane, IDC_SEQUENCE_PIN))
        || GetDlgItem(pane, IDC_SEQUENCE_CELLS) == nullptr
        || GetDlgItem(pane, IDC_SEQUENCE_PREVIOUS) != nullptr
        || GetDlgItem(pane, IDC_SEQUENCE_NEXT) != nullptr
        || GetDlgItem(pane, IDC_SEQUENCE_IMPORT) == nullptr
        || !PaneButtonsFit(pane)) {
        return 868;
    }
    std::array<wchar_t, 256U> target_text{};
    const HWND cells = GetDlgItem(pane, IDC_SEQUENCE_CELLS);
    const auto sequence_style = static_cast<DWORD>(
        GetWindowLongPtrW(cells, GWL_STYLE));
    constexpr DWORD horizontal_sequence_style =
        LBS_MULTICOLUMN | LBS_HASSTRINGS | LBS_DISABLENOSCROLL | WS_HSCROLL;
    if ((sequence_style & horizontal_sequence_style) != horizontal_sequence_style
        || (sequence_style & WS_VSCROLL) != 0U) {
        return 8681;
    }
    if (GetDlgItemTextW(
            pane,
            IDC_SEQUENCE_TARGET,
            target_text.data(),
            static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(
               target_text.data(), UiText(UiStringId::FollowingPrefix))
            != target_text.data()
        || HasJapaneseCharacters(target_text.data())
        || IsWindowEnabled(cells) != FALSE
        || SendMessageW(cells, LB_GETCOUNT, 0, 0) != 0) {
        return 869;
    }
    // Public pane input carries the discovery flag without opening a modal
    // prompt. A subsequent complete view clears the nonpersistent notice.
    try {
        auto limited = state.Workspace().sequence_dialog.view;
        limited.auto_sequence_truncated = true;
        inkpod::windows::ui::panes::UpdateSequencePaneDialog(pane, std::move(limited));
    } catch (const std::bad_alloc&) {
        return 8691;
    }
    if (GetDlgItemTextW(pane, IDC_SEQUENCE_TARGET, target_text.data(),
            static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(target_text.data(), UiText(UiStringId::AutoSequenceTruncated))
            != target_text.data()
        || HasJapaneseCharacters(target_text.data())) {
        return 8692;
    }
    if (!RefreshSequencePane(state)
        || GetDlgItemTextW(pane, IDC_SEQUENCE_TARGET, target_text.data(),
            static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(target_text.data(), UiText(UiStringId::AutoSequenceTruncated)) != nullptr) {
        return 8693;
    }
    if (!VerifyHorizontalSequenceLayout(state)) {
        return 8694;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_SEQUENCE_PIN,
            0) != 1) {
        return 870;
    }
    const auto* binding = state.routing.pane_targets.Find(
        state.routing.sequence_pane);
    target_text.fill(L'\0');
    if (binding == nullptr
        || binding->policy != inkpod::app::PaneTargetPolicy::PinnedDocument
        || GetDlgItemTextW(
               pane,
               IDC_SEQUENCE_TARGET,
               target_text.data(),
               static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(
               target_text.data(), UiText(UiStringId::PinnedPrefix))
            != target_text.data()
        || HasJapaneseCharacters(target_text.data())
        || !PaneButtonsFit(pane)) {
        return 871;
    }
    if (SendMessageW(
            state.Workspace().windows.window,
            WM_COMMAND,
            IDM_SEQUENCE_PIN,
            0) != 1
        || state.routing.pane_targets.Find(state.routing.sequence_pane)->policy
            != inkpod::app::PaneTargetPolicy::FollowActiveView
        || GetDlgItemTextW(
               pane,
               IDC_SEQUENCE_TARGET,
               target_text.data(),
               static_cast<int>(target_text.size())) <= 0
        || std::wcsstr(
               target_text.data(), UiText(UiStringId::FollowingPrefix))
            != target_text.data()
        || HasJapaneseCharacters(target_text.data())) {
        return 872;
    }
    const HWND sequence_header = state.Workspace().windows.dock_host.HeaderWindow(
        DockPaneType::Sequence);
    const HWND sequence_close = GetDlgItem(sequence_header, IDC_RIGHT_TOOL_TAB_CLOSE);
    const auto document_before_close = state.routing.targets.DocumentSession();
    if (sequence_close == nullptr || !WindowHasAccessibleName(sequence_close)) {
        return 8721;
    }
    const HWND tool_tabs = state.Workspace().windows.dock_host.ToolTabWindow();
    const std::array close_buttons{
        TabCloseButtonAt(tool_tabs, TabCtrl_GetCurSel(tool_tabs), IDC_RIGHT_TOOL_TAB_CLOSE),
        sequence_close};
    if (!VerifyTabCloseButtonPainting(close_buttons)) {
        return 8722;
    }
    SendMessageW(sequence_close, BM_CLICK, 0, 0);
    // A queued second close refers to the same now-hidden pane, not the tab
    // that may occupy its former index and not a toggle that opens it again.
    SendMessageW(sequence_header, WM_COMMAND,
        MAKEWPARAM(IDC_RIGHT_TOOL_TAB_CLOSE, BN_CLICKED),
        reinterpret_cast<LPARAM>(sequence_close));
    if (state.Workspace().windows.workspace.dock.IsPaneVisible(
            DockPaneType::Sequence)
        || state.routing.targets.DocumentSession() != document_before_close
        || (GetMenuState(menu, IDM_WINDOW_SEQUENCE, MF_BYCOMMAND) & MF_CHECKED) != 0U) {
        return 873;
    }
    return 0;
}

